const GOUV_ONGLET = {"description": "Une ligne par brief du lundi (calculé par n8n).", "cle": "date", "cle_unique": true, "ecrit_par": ["greeur"], "nom": "Brief", "base": "matos", "colonnes": {"date": {"type": "date", "obligatoire": true, "perso": "non"}, "brief": {"type": "texte", "obligatoire": true, "max": 4000, "perso": "non"}, "ok": {"type": "entier", "obligatoire": true, "min": 0, "perso": "non"}, "surveiller": {"type": "entier", "obligatoire": true, "min": 0, "perso": "non"}, "remplacer": {"type": "entier", "obligatoire": true, "min": 0, "perso": "non"}, "immobilise": {"type": "entier", "obligatoire": true, "min": 0, "perso": "non"}, "budget_12_mois": {"type": "nombre", "obligatoire": true, "perso": "non"}}};
